    s.append(sl(formula('Nguyên lý bù trừ','|A ∪ B| = |A| + |B| − |A ∩ B|')+formula('Ba tập','|A ∪ B ∪ C| = |A|+|B|+|C| − |A∩B| − |A∩C| − |B∩C| + |A∩B∩C|')+formula('Tích Descartes và lũy thừa','|A × B| = |A|·|B|;    |P(A)| = 2^|A|'),'PHẦN 1 · Nền tảng','Lực lượng và bù trừ',
        explain='Cộng |A| + |B| đếm phần chung hai lần nên phải trừ đi một lần. Với ba tập, ta trừ các phần giao đôi (thừa), rồi cộng lại phần giao ba vì nó đã bị trừ quá tay.'))
