    parts.append(dict(title='Phương pháp: xâu bit và độ phức tạp',bullets=['Xâu bit','Big-O','Quy tắc, bảng tăng trưởng'],slides=s))
    s=[]
    s.append(sl(callout('info','Ví dụ 1','Có 120 sinh viên: 60 học Python, 50 Java, 40 C++, 20 Python∩Java, 15 Python∩C++, 10 Java∩C++, 5 cả ba. Bao nhiêu người không học môn nào?')+ol(['|P∪J∪C| = 60+50+40 − 20−15−10 + 5 = 110.','Không học môn nào: 120 − 110 = <b>10</b>.']),'PHẦN 3 · Ví dụ','Ví dụ 1: bù trừ ba tập'))
    s.append(sl(callout('info','Ví dụ 2','Chứng minh (A \\ B) ∪ (A ∩ B) = A.')+ol(['x ∈ vế trái ⇔ (x ∈ A ∧ x ∉ B) ∨ (x ∈ A ∧ x ∈ B).','⇔ x ∈ A ∧ (x ∉ B ∨ x ∈ B)  (phân phối).','⇔ x ∈ A ∧ T ⇔ x ∈ A. ∎']),'PHẦN 3 · Ví dụ','Ví dụ 2: chứng minh đẳng thức tập hợp'))
    s.append(sl(callout('info','Ví dụ 3','Đoạn mã: for i = 1..n: for j = i..n: s += 1. Tính chính xác số lần thực hiện với n = 10 và độ phức tạp.')+ol(['Với i, vòng trong chạy n − i + 1 lần.','Tổng = n + (n−1) + … + 1 = n(n+1)/2 = 55 khi n = 10.','Độ phức tạp: <b>O(n²)</b>.']),'PHẦN 3 · Ví dụ','Ví dụ 3: đếm phép toán'))
    s.append(sl(callout('info','Ví dụ 4','Máy thực hiện 10⁹ phép/giây. Vét cạn 2ⁿ với n = 40 tốn bao lâu?')+ol(['2⁴⁰ = 1 099 511 627 776 ≈ 1,1·10¹² phép.','Thời gian ≈ 1,1·10¹² / 10⁹ ≈ 1100 giây ≈ 18 phút.','Với n = 60: 2⁶⁰ ≈ 1,15·10¹⁸ ⇒ khoảng 36 năm. Đây là lý do cần nhánh cận (Module 12).']),'PHẦN 3 · Ví dụ','Ví dụ 4: ước lượng thời gian'))
