    s.append(sl('<p>Ngoài O còn có Ω (cận dưới) và Θ (cận chặt): f = Θ(g) ⇔ f = O(g) và f = Ω(g). Ví dụ (n² + n)/2 = Θ(n²).</p>','PHẦN 4 · Bẫy và mở rộng','Mở rộng: Ω và Θ'))
    parts.append(dict(title='Bẫy và mở rộng',bullets=['Năm bẫy','Ω và Θ'],slides=s))
    s=[]
