    notes+=ex('3. Số tập con','<p>Tập 10 phần tử có 2¹⁰ = 1024 tập con; có C(10,3) = 120 tập con 3 phần tử; có 2¹⁰ − 1 tập con khác rỗng. Số quan hệ hai ngôi trên tập 10 phần tử: 2^(10·10) = 2¹⁰⁰.</p>')
    notes+=ex('4. Big-O','<table class="t left"><tr><th>f(n)</th><th>Big-O chặt</th><th>Lý do</th></tr><tr><td>3n² + 5n + 100</td><td>O(n²)</td><td>số hạng bậc cao nhất</td></tr><tr><td>7n·log n + 3n</td><td>O(n log n)</td><td>n log n trội hơn n</td></tr><tr><td>5·2ⁿ + n¹⁰</td><td>O(2ⁿ)</td><td>hàm mũ trội hơn mọi đa thức</td></tr><tr><td>n! + 2ⁿ</td><td>O(n!)</td><td>n! trội hơn 2ⁿ</td></tr></table>')
